mapper.insert:
SELECT AYE100_SQ01.CURRVAL AS BBSCTT_ESNTAL_NO FROM DUAL
INSERT INTO AYE100 ( /*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsEpilogoListMapper : 사이버상담후기(등록)*/ BBSCTT_ESNTAL_NO /*게시글번호*/ , BBSCTT_TYPE_SE_CD /*게시글구분코드*/
, BBSCTT_TTL_NM /*게시글제목명*/
, WRTR_NM_ENCPT /*작성자*/
, BBSCTT_CN /*게시글내용*/
, CNTN_IP_ADDR /*아이피주소*/
, EML_ADDR_ENCPT /*이메일주소*/
, SXDC_SE_CD /*성별*/
, BRTH_YMD /*출생일자*/
, MBL_TELNO_ENCPT /*폰번호*/
, ATFINO /*파일*/
, ACBG_SE_CD /* 학력구분코드 */ , GRADE_SE_CD /* 학년구분코드 */ , NTABRD_CSC_OCCP_SE_CD /* 게시판상담실직업구분코드 */ , PROBM_STTS_LCLAS_SE_CD /* 문제상태대분류구분코드 */ , PROBM_STTS_MLSFC_SE_CD /* 문제상태중분류구분코드 */ , PROBM_STTS_SCLAS_SE_CD /* 문제상태소분류구분코드 */ , PROBM_CAS_LCLAS_SE_CD /* 문제원인대분류구분코드 */ , PROBM_CAS_SCLAS_SE_CD /* 문제원인소분류구분코드 */ , ETC_CN /* 기타내용 */ , FRST_REG_DT /*최초등록일자*/ , FRST_RGTR_ID /*최초등록아이디*/ , DEL_YN /*삭제여부*/ ) VALUES( AYE100_SQ01.NEXTVAL , '12'
, #{BBSCTT_TTL_NM}
, C##RG.ENC_B64(#{WRTR_NM_ENCPT})
, #{BBSCTT_CN}
, #{CNTN_IP_ADDR}
, #{EML_ADDR_ENCPT}
, #{SXDC_SE_CD}
, #{BRTH_YMD}
, #{MBL_TELNO_ENCPT} /*폰번호*/
, #{ATFINO}
, #{ACBG_SE_CD} /* 학력구분코드 */ , #{GRADE_SE_CD} /* 학년구분코드 */ , #{NTABRD_CSC_OCCP_SE_CD} /* 게시판상담실직업구분코드 */ , #{PROBM_STTS_LCLAS_SE_CD} /* 문제상태대분류구분코드 */ , #{PROBM_STTS_MLSFC_SE_CD} /* 문제상태중분류구분코드 */ , #{PROBM_STTS_SCLAS_SE_CD} /* 문제상태소분류구분코드 */ , #{PROBM_CAS_LCLAS_SE_CD} /* 문제원인대분류구분코드 */ , #{PROBM_CAS_SCLAS_SE_CD} /* 문제원인소분류구분코드 */ , #{ETC_CN} /* 기타내용 */ , TO_DATE(#{FRST_REG_DT},'YYYY-MM-DD') , #{FRST_RGTR_ID} , 'N' )

mapper.update:
/*SQL-ID : isry.couns.constt.medscsnntabrd.mapper.BbsmomListMapper :  자녀맘터치법(조회수)*/
UPDATE AYE100 SET
    RDCNT_NOCS = NVL(TO_NUMBER(RDCNT_NOCS), 0) +1
WHERE 1=1
AND BBSCTT_TYPE_SE_CD = '12'
AND BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}

    /*
     * SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsEpilogoListMapper.updateBbsRespodEpilogo :  사이버상담후기(답글수정)
     * 2023.04.26 수정 : 불필요한 컬럼 삭제 / AND 조건 : 게시글고유번호 + 게시글유형구분코드 ▷ 답글고유번호 로 변경 - Jeong.Won.Je
     */
	     UPDATE 
	            AYE120 
	     SET    
	            RETE_TTL_NM         =       #{RETE_TTL_NM}
	          , RETE_CN             =       #{RETE_CN} 
	          , LAST_MDFR_ID        =       #{LAST_MDFR_ID}
	          , LAST_MDFCN_DT       =       SYSDATE 
	     WHERE  1=1
	     AND    RETE_ESNTAL_NO      =       #{RETE_ESNTAL_NO}

UPDATE AYE100 SET /*SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsEpilogoListMapper.updateBbsRespodEpilogo100 :  사이버상담후기(답글수정)*/
            NTABRD_CSC_OCCP_SE_CD = #{NTABRD_CSC_OCCP_SE_CD}
            ,ACBG_SE_CD = #{ACBG_SE_CD}                  
            ,GRADE_SE_CD = #{GRADE_SE_CD}
            ,SXDC_SE_CD = #{SXDC_SE_CD}
            ,PROBM_STTS_LCLAS_SE_CD = #{PROBM_STTS_LCLAS_SE_CD}
            ,PROBM_STTS_MLSFC_SE_CD = #{PROBM_STTS_MLSFC_SE_CD}
            ,PROBM_STTS_SCLAS_SE_CD = #{PROBM_STTS_SCLAS_SE_CD}
            ,PROBM_CAS_LCLAS_SE_CD = #{PROBM_CAS_LCLAS_SE_CD}
            ,PROBM_CAS_SCLAS_SE_CD = #{PROBM_CAS_SCLAS_SE_CD}
            ,ETC_CN = #{ETC_CN}
            ,LAST_MDFCN_DT = SYSDATE 
            ,LAST_MDFR_ID = #{LAST_MDFR_ID}                    
WHERE       1=1
    AND     BBSCTT_TYPE_SE_CD = '12'
    AND     BBSCTT_ESNTAL_NO = #{BBSCTT_ESNTAL_NO}

    /*
     * SQL-ID : isry.couns.constt.etcntabrd.mapper.BbsEpilogoListMapper.processEpilgMemo :  사이버상담후기 메모 저장/수정
     * 2023.04.26 : 추가 - Jeong.Won.Je
     */
		MERGE
		INTO  AYA160    T1
		USING DUAL
		ON    (
		           T1.BBSCTT_ESNTAL_NO   =   #{BBSCTT_ESNTAL_NO}
		       AND T1.BBSCTT_TYPE_SE_CD  =   #{BBSCTT_TYPE_SE_CD}
		      )
		WHEN MATCHED THEN
		    UPDATE
		    SET      T1.MEMO_NM         =   #{MEMO_NM}
		           , T1.LAST_MDFR_ID    =   #{loginId}
		           , T1.LAST_MDFCN_DT   =   SYSDATE
		WHEN NOT MATCHED THEN
		    INSERT (
		            RFRNC_NO
		            , BBSCTT_ESNTAL_NO
		            , BBSCTT_TYPE_SE_CD
		            , CONSTT_ID
		            , MEMO_NM
		            , FRST_RGTR_ID
		            , FRST_REG_DT
		            , LAST_MDFR_ID
		            , LAST_MDFCN_DT
		           )
		    VALUES (
		            AYA160_SQ01.NEXTVAL
		            , #{BBSCTT_ESNTAL_NO}
		            , #{BBSCTT_TYPE_SE_CD}
		            , #{loginId}
		            , #{MEMO_NM}
		            , #{loginId}
		            , SYSDATE
		            , #{loginId}
		            , SYSDATE
		           )
